    // ---------- HELPERS ----------
    function formatTimeAgo(ts) {
      const diff = Math.max(1, Math.floor((Date.now() - ts) / 60000));
      if (diff < 60) return `${diff}m ago`;
      const hrs = Math.floor(diff / 60);
      if (hrs < 24) return `${hrs}h ago`;
      return `${Math.floor(hrs / 24)}d ago`;
    }

    function escapeHtml(str) {
      return String(str).replace(/[&<>"']/g, s => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      }[s]));
    }

    function showToast(msg, tone = 'info') {
      const wrap = document.getElementById('toast-container');
      const colors = {
        info: 'bg-slate-900 text-white dark:bg-slate-800',
        success: 'bg-emerald-600 text-white',
        error: 'bg-rose-600 text-white'
      };
      const el = document.createElement('div');
      el.className = `pointer-events-auto px-4 py-2.5 rounded-xl shadow-lg text-xs sm:text-sm font-medium ${colors[tone] || colors.info} transition-opacity`;
      el.textContent = msg;
      wrap.appendChild(el);
      setTimeout(() => { el.style.opacity = '0'; setTimeout(() => el.remove(), 250); }, 2800);
    }

    function nearestLandmark(lat, lng) {
      let best = LPU_LANDMARKS[0];
      let bestDist = Infinity;
      LPU_LANDMARKS.forEach(lm => {
        const d = Math.hypot(lm.lat - lat, lm.lng - lng);
        if (d < bestDist) { bestDist = d; best = lm; }
      });
      return `Near ${best.name}`;
    }

    // ---------- NAVIGATION & THEME ----------
    function setView(viewName) {
      state.activeView = viewName;
      document.querySelectorAll('.view-section').forEach(sec => sec.classList.add('hidden'));
      const target = document.getElementById(`view-${viewName}`);
      if (target) target.classList.remove('hidden');

      document.querySelectorAll('.nav-btn').forEach(btn => {
        const isCurrent = btn.dataset.nav === viewName || (viewName === 'home' && state.searchOpen && btn.dataset.nav === 'search');
        btn.classList.toggle('bg-lpu-50', isCurrent);
        btn.classList.toggle('dark:bg-lpu-700/20', isCurrent);
        btn.classList.toggle('text-lpu-600', isCurrent);
        btn.classList.toggle('dark:text-lpu-500', isCurrent);
        btn.classList.toggle('text-slate-600', !isCurrent);
        btn.classList.toggle('dark:text-slate-300', !isCurrent);
      });

      if (viewName === 'home') renderFeed();
      if (viewName === 'messages') renderMessagesView();
      if (viewName === 'profile') renderProfileView();
      if (viewName === 'map') {
        setTimeout(() => { initCampusMap(); campusMap.invalidateSize(); renderCampusMarkers(); }, 60);
      }
      if (viewName === 'add' && !document.getElementById('mini-map-wrapper').classList.contains('hidden')) {
        setTimeout(() => { initMiniMap(); miniMap.invalidateSize(); }, 60);
      }
    }

    function applyTheme(theme) {
      state.theme = theme;
      const html = document.documentElement;
      if (theme === 'dark') html.classList.add('dark');
      else html.classList.remove('dark');

      const lightBtn = document.getElementById('theme-light-btn');
      const darkBtn = document.getElementById('theme-dark-btn');
      if (lightBtn && darkBtn) {
        lightBtn.className = `px-3 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${theme === 'light' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`;
        darkBtn.className = `px-3 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${theme === 'dark' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-500 dark:text-slate-400'}`;
      }
    }

    // ---------- HOME FEED & SEARCH ----------
    function getFilteredPosts() {
      const kw = state.searchKeyword.trim().toLowerCase();
      let list = state.posts.filter(p => {
        if (state.feedFilter === 'lost' && p.type !== 'lost') return false;
        if (state.feedFilter === 'found' && p.type !== 'found') return false;
        if (state.feedFilter === 'returned' && p.status !== 'returned') return false;
        if (state.searchType !== 'all' && p.type !== state.searchType) return false;
        if (state.searchCategory !== 'all' && p.category !== state.searchCategory) return false;
        if (kw) {
          const hay = `${p.title} ${p.description} ${p.category} ${p.incidentLocation.label} ${p.pickupLocation.label}`.toLowerCase();
          if (!hay.includes(kw)) return false;
        }
        return true;
      });

      if (kw) {
        list.sort((a, b) => {
          const aTitle = a.title.toLowerCase().includes(kw) ? 1 : 0;
          const bTitle = b.title.toLowerCase().includes(kw) ? 1 : 0;
          if (bTitle !== aTitle) return bTitle - aTitle;
          return b.createdAt - a.createdAt;
        });
      } else {
        list.sort((a, b) => b.createdAt - a.createdAt);
      }
      return list;
    }

    function renderFeed() {
      const container = document.getElementById('feed-container');
      const posts = getFilteredPosts();
      const countEl = document.getElementById('search-result-count');
      if (countEl) countEl.textContent = `Showing ${posts.length} ${posts.length === 1 ? 'post' : 'posts'}`;

      document.querySelectorAll('.feed-chip').forEach(chip => {
        const active = chip.dataset.feedFilter === state.feedFilter;
        chip.className = `feed-chip px-3.5 py-1.5 rounded-full text-xs font-semibold transition cursor-pointer ${active ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900' : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300'}`;
      });

      if (!posts.length) {
        container.innerHTML = `
          <div class="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-10 text-center">
            <p class="font-semibold text-base mb-1">No matching items found</p>
            <p class="text-sm text-slate-500 dark:text-slate-400">Try a different keyword, property type, or reset filters.</p>
          </div>`;
        return;
      }

      container.innerHTML = posts.map(post => {
        const author = state.users[post.authorId] || state.currentUser;
        const isLost = post.type === 'lost';
        const isReturned = post.status === 'returned';
        const badgeHtml = isReturned
          ? `<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold uppercase tracking-wide bg-slate-200 text-slate-800 dark:bg-slate-700 dark:text-slate-200">Returned &amp; Verified</span>`
          : isLost
            ? `<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold uppercase tracking-wide bg-rose-100 text-rose-700 dark:bg-rose-950 dark:text-rose-300 border border-rose-200 dark:border-rose-800">LOST ITEM</span>`
            : `<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold uppercase tracking-wide bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800">FOUND ITEM</span>`;

        const imgHtml = post.image
          ? `<div class="bg-slate-100 dark:bg-slate-800 max-h-[420px] overflow-hidden"><img src="${post.image}" alt="${escapeHtml(post.title)}" class="w-full h-80 object-cover" /></div>`
          : `<div class="bg-slate-100 dark:bg-slate-800 h-52 flex flex-col items-center justify-center text-slate-400 dark:text-slate-500"><i data-lucide="package" class="w-10 h-10 mb-2"></i><span class="text-xs font-medium">${escapeHtml(post.category)}</span></div>`;

        return `
          <article class="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm overflow-hidden">
            <!-- Badge Above Post to Differentiate Lost & Found -->
            <div class="px-4 pt-3 pb-2 flex items-center justify-between border-b border-slate-100 dark:border-slate-800/80 bg-slate-50/70 dark:bg-slate-900">
              <div class="flex items-center gap-2">
                ${badgeHtml}
                <span class="text-xs font-medium text-slate-500 dark:text-slate-400">${escapeHtml(post.category)}</span>
              </div>
              <span class="text-xs text-slate-400">${formatTimeAgo(post.createdAt)}</span>
            </div>

            <!-- Instagram-like Post Header -->
            <div class="px-4 py-3 flex items-center justify-between gap-3">
              <div class="flex items-center gap-3 min-w-0">
                <div class="w-9 h-9 rounded-full bg-gradient-to-br from-lpu-500 to-amber-500 text-white flex items-center justify-center font-bold text-xs shrink-0">${escapeHtml(author.initials)}</div>
                <div class="min-w-0">
                  <div class="flex items-center gap-1.5">
                    <span class="font-semibold text-sm truncate">${escapeHtml(author.name)}</span>
                    <span class="text-xs text-slate-400 truncate">@${escapeHtml(author.username)}</span>
                  </div>
                  <div class="text-xs text-slate-500 dark:text-slate-400 truncate">${escapeHtml(post.incidentLocation.label)}</div>
                </div>
              </div>
              <div class="flex items-center gap-2 shrink-0">
                <span class="px-2 py-0.5 rounded-full bg-amber-50 dark:bg-amber-950/50 text-amber-700 dark:text-amber-300 text-[11px] font-semibold border border-amber-200/80 dark:border-amber-800/60">
                  ${author.helpScore} pts
                </span>
                ${post.authorId !== state.currentUser.id ? `
                  <button data-chat-author="${post.authorId}" data-chat-post="${post.id}" type="button" class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-lpu-600 hover:bg-lpu-700 text-white text-xs font-semibold transition cursor-pointer">
                    <i data-lucide="message-circle" class="w-3.5 h-3.5"></i>
                    <span>Chat</span>
                  </button>` : ''}
              </div>
            </div>

            <!-- Photo -->
            ${imgHtml}

            <!-- Post Body & Action Bar -->
            <div class="p-4 space-y-3">
              <div class="flex flex-wrap items-center justify-between gap-2">
                <h3 class="font-bold text-base">${escapeHtml(post.title)}</h3>
                <div class="flex items-center gap-2">
                  <button data-view-pin="${post.id}" type="button" class="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-xs font-semibold transition cursor-pointer">
                    <i data-lucide="map-pin" class="w-3.5 h-3.5 text-lpu-600"></i>
                    <span>Map Pin</span>
                  </button>
                  ${post.status === 'active' ? `
                    <button data-return-post="${post.id}" type="button" class="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-emerald-50 dark:bg-emerald-950/40 hover:bg-emerald-100 dark:hover:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 text-xs font-semibold transition cursor-pointer">
                      <i data-lucide="check-circle-2" class="w-3.5 h-3.5"></i>
                      <span>Confirm Legit Return (+25 pts)</span>
                    </button>` : ''}
                </div>
              </div>

              <p class="text-sm text-slate-700 dark:text-slate-300 leading-relaxed">${escapeHtml(post.description)}</p>

              <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1 text-xs">
                <div class="px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/70 border border-slate-200/70 dark:border-slate-700/70">
                  <span class="font-semibold text-slate-500 dark:text-slate-400 block">${isLost ? 'Lost Near:' : 'Found At:'}</span>
                  <span class="font-medium text-slate-800 dark:text-slate-200">${escapeHtml(post.incidentLocation.label)}</span>
                </div>
                <div class="px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/70 border border-slate-200/70 dark:border-slate-700/70">
                  <span class="font-semibold text-slate-500 dark:text-slate-400 block">Pickup / Collection Point:</span>
                  <span class="font-medium text-slate-800 dark:text-slate-200">${escapeHtml(post.pickupLocation.label)}</span>
                </div>
              </div>
            </div>
          </article>
        `;
      }).join('');
      lucide.createIcons();
    }

    // ---------- HELP SCORE ----------
    function awardHelpScore(postId) {
      const post = state.posts.find(p => p.id === postId);
      if (!post || post.status === 'returned') return;
      post.status = 'returned';

      // Award +25 help points to the user who returned/helped (poster for found items, or current user if helping on a lost item)
      const helperId = post.type === 'found' ? post.authorId : state.currentUser.id;
      const helper = state.users[helperId] || state.currentUser;
      helper.helpScore += 25;
      if (helperId === state.currentUser.id) {
        state.currentUser.helpScore = helper.helpScore;
      }
      document.getElementById('header-help-score').textContent = state.currentUser.helpScore;
      showToast(`Legit return confirmed! +25 Help Points awarded to ${helper.name}.`, 'success');
      renderFeed();
      if (state.activeView === 'messages') renderMessagesView();
      if (state.activeView === 'profile') renderProfileView();
    }

    // ---------- MESSAGES (Latest to Oldest + Chat) ----------
    function openChatWithUser(partnerId, postId = null) {
      if (!state.conversations[partnerId]) {
        state.conversations[partnerId] = {
          partnerId,
          postId,
          messages: [
            { id: 'm_' + Date.now(), senderId: partnerId, text: 'Hi! Reach out here regarding the campus item.', timestamp: Date.now() }
          ]
        };
      } else if (postId) {
        state.conversations[partnerId].postId = postId;
      }
      state.activeChatUserId = partnerId;
      setView('messages');
    }

    function getSortedConversations() {
      return Object.values(state.conversations).sort((a, b) => {
        const aLast = a.messages.length ? a.messages[a.messages.length - 1].timestamp : 0;
        const bLast = b.messages.length ? b.messages[b.messages.length - 1].timestamp : 0;
        return bLast - aLast;
      });
    }

    function renderMessagesView() {
      const listEl = document.getElementById('conversation-list');
      const convos = getSortedConversations();

      listEl.innerHTML = convos.map(c => {
        const partner = state.users[c.partnerId];
        const lastMsg = c.messages[c.messages.length - 1];
        const active = c.partnerId === state.activeChatUserId;
        return `
          <button data-select-chat="${c.partnerId}" type="button" class="w-full text-left p-3.5 flex items-center gap-3 transition cursor-pointer ${active ? 'bg-lpu-50 dark:bg-lpu-700/20' : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'}">
            <div class="w-10 h-10 rounded-full bg-gradient-to-br from-lpu-500 to-amber-500 text-white flex items-center justify-center font-bold text-xs shrink-0">${escapeHtml(partner.initials)}</div>
            <div class="min-w-0 flex-1">
              <div class="flex items-center justify-between gap-2">
                <span class="font-semibold text-sm truncate">${escapeHtml(partner.name)}</span>
                <span class="text-[11px] text-slate-400 shrink-0">${lastMsg ? formatTimeAgo(lastMsg.timestamp) : ''}</span>
              </div>
              <div class="text-xs text-slate-500 dark:text-slate-400 truncate">@${escapeHtml(partner.username)} · ${lastMsg ? escapeHtml(lastMsg.text) : 'No messages yet'}</div>
            </div>
          </button>
        `;
      }).join('');

      const activeConvo = state.conversations[state.activeChatUserId];
      const chatInput = document.getElementById('chat-input');
      const chatSendBtn = document.getElementById('chat-send-btn');
      const confirmBtn = document.getElementById('chat-confirm-return-btn');
      const messagesEl = document.getElementById('chat-messages');

      if (!activeConvo) {
        chatInput.disabled = true;
        chatSendBtn.disabled = true;
        confirmBtn.classList.add('hidden');
        messagesEl.innerHTML = '<div class="text-center text-sm text-slate-400 py-12">Select a user from the list to view messages.</div>';
        return;
      }

      const partner = state.users[activeConvo.partnerId];
      document.getElementById('chat-partner-avatar').textContent = partner.initials;
      document.getElementById('chat-partner-name').textContent = partner.name;
      document.getElementById('chat-partner-sub').textContent = `@${partner.username} · Help Score: ${partner.helpScore} pts`;

      const linkedPost = state.posts.find(p => p.id === activeConvo.postId);
      if (linkedPost && linkedPost.status === 'active') {
        confirmBtn.classList.remove('hidden');
        confirmBtn.dataset.postId = linkedPost.id;
      } else {
        confirmBtn.classList.add('hidden');
      }

      chatInput.disabled = false;
      chatSendBtn.disabled = false;

      messagesEl.innerHTML = activeConvo.messages.map(m => {
        const mine = m.senderId === state.currentUser.id;
        return `
          <div class="flex ${mine ? 'justify-end' : 'justify-start'}">
            <div class="max-w-[78%] px-3.5 py-2.5 rounded-2xl text-sm ${mine ? 'bg-lpu-600 text-white rounded-br-sm' : 'bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-bl-sm'}">
              <p>${escapeHtml(m.text)}</p>
              <span class="block text-[10px] mt-1 ${mine ? 'text-orange-100' : 'text-slate-400'}">${formatTimeAgo(m.timestamp)}</span>
            </div>
          </div>
        `;
      }).join('');
      messagesEl.scrollTop = messagesEl.scrollHeight;
    }

    // ---------- LEAFLET MAPS (Uploaded LPU Campus Map Overlay) ----------
    let campusMap = null;
    let campusMarkersLayer = null;

    function initCampusMap() {
      if (campusMap) return;
      campusMap = L.map('campus-map', {
        crs: L.CRS.Simple,
        minZoom: -1,
        maxZoom: 2,
        maxBounds: [[-100, -100], [1028, 1043]]
      });
      L.imageOverlay(LPU_MAP_IMAGE, LPU_MAP_BOUNDS).addTo(campusMap);
      campusMap.fitBounds(LPU_MAP_BOUNDS);
      campusMarkersLayer = L.layerGroup().addTo(campusMap);
    }

    function makeDotIcon(color) {
      return L.divIcon({
        className: 'custom-pin',
        html: `<div style="width:16px;height:16px;border-radius:9999px;background:${color};border:2.5px solid #fff;box-shadow:0 2px 6px rgba(0,0,0,.35);"></div>`,
        iconSize: [16, 16],
        iconAnchor: [8, 8]
      });
    }

    function renderCampusMarkers(focusPostId = null) {
      if (!campusMap || !campusMarkersLayer) return;
      campusMarkersLayer.clearLayers();

      document.querySelectorAll('.map-filter-btn').forEach(btn => {
        const active = btn.dataset.mapFilter === state.mapFilter;
        btn.className = `map-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${active ? 'bg-lpu-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300'}`;
      });

      // Campus Landmarks
      LPU_LANDMARKS.forEach(lm => {
        L.marker([lm.lat, lm.lng], { icon: makeDotIcon('#f59e0b') })
          .bindPopup(`<strong>${escapeHtml(lm.name)}</strong><br/><span style="font-size:11px;color:#64748b;">${escapeHtml(lm.note || 'LPU Campus Block')}</span>`)
          .addTo(campusMarkersLayer);
      });

      // Assigned Post Locations
      state.posts.forEach(post => {
        const showIncident = state.mapFilter === 'all' || state.mapFilter === post.type;
        const showPickup = state.mapFilter === 'all' || state.mapFilter === 'pickup';
        const author = state.users[post.authorId] || state.currentUser;

        if (showIncident) {
          const color = post.type === 'lost' ? '#e11d48' : '#10b981';
          const marker = L.marker([post.incidentLocation.lat, post.incidentLocation.lng], { icon: makeDotIcon(color) })
            .bindPopup(`
              <div style="min-width:180px;">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;color:${color};">${post.type.toUpperCase()} ITEM</div>
                <div style="font-weight:700;font-size:13px;margin:2px 0;">${escapeHtml(post.title)}</div>
                <div style="font-size:11px;color:#475569;margin-bottom:6px;">Spot: ${escapeHtml(post.incidentLocation.label)}<br/>By @${escapeHtml(author.username)}</div>
                <button onclick="openChatFromMap('${post.authorId}','${post.id}')" style="background:#ea580c;color:#fff;border:none;border-radius:6px;padding:4px 10px;font-size:11px;font-weight:600;cursor:pointer;">Chat with Poster</button>
              </div>
            `)
            .addTo(campusMarkersLayer);
          if (focusPostId === post.id) {
            campusMap.setView([post.incidentLocation.lat, post.incidentLocation.lng], 1);
            marker.openPopup();
          }
        }

        if (showPickup) {
          L.marker([post.pickupLocation.lat, post.pickupLocation.lng], { icon: makeDotIcon('#3b82f6') })
            .bindPopup(`
              <div style="min-width:170px;">
                <div style="font-size:10px;font-weight:700;text-transform:uppercase;color:#2563eb;">PICKUP / COLLECTION POINT</div>
                <div style="font-weight:700;font-size:13px;margin:2px 0;">${escapeHtml(post.title)}</div>
                <div style="font-size:11px;color:#475569;">${escapeHtml(post.pickupLocation.label)}</div>
              </div>
            `)
            .addTo(campusMarkersLayer);
        }
      });
    }

    window.openChatFromMap = function(authorId, postId) {
      if (authorId === state.currentUser.id) {
        showToast('This is your own post!', 'info');
        return;
      }
      openChatWithUser(authorId, postId);
    };

    // Small Mini-Map for Add Post
    let miniMap = null;
    let miniIncidentMarker = null;
    let miniPickupMarker = null;

    function initMiniMap() {
      if (miniMap) return;
      miniMap = L.map('mini-map', {
        crs: L.CRS.Simple,
        minZoom: -1,
        maxZoom: 2,
        maxBounds: [[-80, -80], [1008, 1023]]
      });
      L.imageOverlay(LPU_MAP_IMAGE, LPU_MAP_BOUNDS).addTo(miniMap);
      miniMap.fitBounds(LPU_MAP_BOUNDS);

      LPU_LANDMARKS.forEach(lm => {
        L.marker([lm.lat, lm.lng], { icon: makeDotIcon('#f59e0b') })
          .bindTooltip(lm.name, { direction: 'top', offset: [0, -6] })
          .addTo(miniMap);
      });

      miniIncidentMarker = L.marker([state.draftLocation.incidentLat, state.draftLocation.incidentLng], { icon: makeDotIcon('#e11d48') }).addTo(miniMap);
      miniPickupMarker = L.marker([state.draftLocation.pickupLat, state.draftLocation.pickupLng], { icon: makeDotIcon('#10b981') }).addTo(miniMap);

      miniMap.on('click', e => {
        const { lat, lng } = e.latlng;
        document.getElementById('mini-map-coords').textContent = `Map (${Math.round(lng)}, ${Math.round(lat)})`;
        const lmLabel = nearestLandmark(lat, lng);
        if (state.draftLocation.pickingMode === 'incident') {
          state.draftLocation.incidentLat = lat;
          state.draftLocation.incidentLng = lng;
          miniIncidentMarker.setLatLng([lat, lng]);
          document.getElementById('post-incident-loc').value = lmLabel;
        } else {
          state.draftLocation.pickupLat = lat;
          state.draftLocation.pickupLng = lng;
          miniPickupMarker.setLatLng([lat, lng]);
          document.getElementById('post-pickup-loc').value = lmLabel;
        }
      });
    }

    function setMiniMapMode(mode) {
      state.draftLocation.pickingMode = mode;
      const incBtn = document.getElementById('mode-incident-btn');
      const pickBtn = document.getElementById('mode-pickup-btn');
      if (mode === 'incident') {
        incBtn.className = 'px-2.5 py-1 rounded-lg bg-rose-600 text-white font-semibold cursor-pointer';
        pickBtn.className = 'px-2.5 py-1 rounded-lg bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold cursor-pointer';
      } else {
        pickBtn.className = 'px-2.5 py-1 rounded-lg bg-emerald-600 text-white font-semibold cursor-pointer';
        incBtn.className = 'px-2.5 py-1 rounded-lg bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold cursor-pointer';
      }
    }

    // ---------- PROFILE & SETTINGS ----------
    function renderProfileView() {
      const u = state.currentUser;
      document.getElementById('profile-avatar').textContent = u.initials;
      document.getElementById('profile-name').textContent = u.name;
      document.getElementById('profile-username').textContent = `@${u.username}`;
      document.getElementById('profile-help-score').textContent = u.helpScore;
      document.getElementById('header-help-score').textContent = u.helpScore;
      document.getElementById('new-username-input').value = u.username;

      const myPosts = state.posts.filter(p => p.authorId === u.id);
      const listEl = document.getElementById('profile-posts-list');
      if (!myPosts.length) {
        listEl.innerHTML = '<p class="text-sm text-slate-500 dark:text-slate-400">You have not posted any lost or found items yet.</p>';
        return;
      }
      listEl.innerHTML = myPosts.map(p => `
        <div class="p-3.5 rounded-xl border border-slate-200 dark:border-slate-800 flex items-center justify-between gap-3">
          <div class="min-w-0">
            <div class="flex items-center gap-2">
              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${p.type === 'lost' ? 'bg-rose-100 text-rose-700 dark:bg-rose-950 dark:text-rose-300' : 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300'}">${p.type}</span>
              <span class="font-semibold text-sm truncate">${escapeHtml(p.title)}</span>
            </div>
            <p class="text-xs text-slate-500 dark:text-slate-400 mt-0.5 truncate">${escapeHtml(p.incidentLocation.label)}</p>
          </div>
          <span class="text-xs font-semibold ${p.status === 'returned' ? 'text-emerald-600' : 'text-amber-600'}">${p.status === 'returned' ? 'Returned' : 'Active'}</span>
        </div>
      `).join('');
    }

    // ---------- EVENT WIRING ----------
    document.addEventListener('DOMContentLoaded', () => {
      lucide.createIcons();
      applyTheme('light');
      setView('home');

      // Nav buttons
      document.querySelectorAll('.nav-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const nav = btn.dataset.nav;
          if (nav === 'search') {
            state.searchOpen = true;
            setView('home');
            document.getElementById('search-panel').classList.remove('hidden');
            document.getElementById('search-keyword').focus();
          } else {
            if (nav === 'home') state.searchOpen = false;
            setView(nav);
          }
        });
      });

      document.getElementById('brand-home-btn').addEventListener('click', () => {
        state.searchOpen = false;
        document.getElementById('search-panel').classList.add('hidden');
        setView('home');
      });

      document.getElementById('header-score-btn').addEventListener('click', () => setView('profile'));
      document.getElementById('home-quick-add-btn').addEventListener('click', () => setView('add'));
      document.getElementById('cancel-add-btn').addEventListener('click', () => setView('home'));

      // Feed filter chips
      document.querySelectorAll('.feed-chip').forEach(chip => {
        chip.addEventListener('click', () => {
          state.feedFilter = chip.dataset.feedFilter;
          renderFeed();
        });
      });

      // Search panel controls
      document.getElementById('close-search-btn').addEventListener('click', () => {
        state.searchOpen = false;
        document.getElementById('search-panel').classList.add('hidden');
      });
      document.getElementById('search-keyword').addEventListener('input', e => {
        state.searchKeyword = e.target.value;
        renderFeed();
      });
      document.getElementById('search-category').addEventListener('change', e => {
        state.searchCategory = e.target.value;
        renderFeed();
      });
      document.getElementById('search-type').addEventListener('change', e => {
        state.searchType = e.target.value;
        renderFeed();
      });
      document.getElementById('reset-search-btn').addEventListener('click', () => {
        state.searchKeyword = '';
        state.searchCategory = 'all';
        state.searchType = 'all';
        state.feedFilter = 'all';
        document.getElementById('search-keyword').value = '';
        document.getElementById('search-category').value = 'all';
        document.getElementById('search-type').value = 'all';
        renderFeed();
      });

      // Feed delegation (Chat, Map Pin, Confirm Return)
      document.getElementById('feed-container').addEventListener('click', e => {
        const chatBtn = e.target.closest('[data-chat-author]');
        if (chatBtn) {
          openChatWithUser(chatBtn.dataset.chatAuthor, chatBtn.dataset.chatPost);
          return;
        }
        const pinBtn = e.target.closest('[data-view-pin]');
        if (pinBtn) {
          const postId = pinBtn.dataset.viewPin;
          setView('map');
          setTimeout(() => { initCampusMap(); campusMap.invalidateSize(); renderCampusMarkers(postId); }, 80);
          return;
        }
        const retBtn = e.target.closest('[data-return-post]');
        if (retBtn) {
          awardHelpScore(retBtn.dataset.returnPost);
        }
      });

      // Add Post Photo upload
      document.getElementById('post-photo-input').addEventListener('change', e => {
        const file = e.target.files[0];
        if (!file) return;
        document.getElementById('post-photo-name').textContent = file.name;
        const reader = new FileReader();
        reader.onload = ev => {
          state.draftLocation.uploadedImage = ev.target.result;
          document.getElementById('post-photo-preview').src = ev.target.result;
          document.getElementById('post-photo-preview-wrap').classList.remove('hidden');
        };
        reader.readAsDataURL(file);
      });

      document.getElementById('remove-photo-btn').addEventListener('click', () => {
        state.draftLocation.uploadedImage = '';
        document.getElementById('post-photo-input').value = '';
        document.getElementById('post-photo-name').textContent = 'Optional: upload a photo from your device';
        document.getElementById('post-photo-preview-wrap').classList.add('hidden');
      });

      // Mini-map controls in Add Post
      function openMiniMap(mode) {
        const wrap = document.getElementById('mini-map-wrapper');
        wrap.classList.remove('hidden');
        document.getElementById('mini-map-toggle-label').textContent = 'Hide Small Campus Map';
        setMiniMapMode(mode);
        setTimeout(() => { initMiniMap(); miniMap.invalidateSize(); }, 60);
      }

      document.getElementById('toggle-mini-map-btn').addEventListener('click', () => {
        const wrap = document.getElementById('mini-map-wrapper');
        if (wrap.classList.contains('hidden')) {
          openMiniMap(state.draftLocation.pickingMode);
        } else {
          wrap.classList.add('hidden');
          document.getElementById('mini-map-toggle-label').textContent = 'Open Small Campus Map';
        }
      });
      document.getElementById('pick-incident-pin-btn').addEventListener('click', () => openMiniMap('incident'));
      document.getElementById('pick-pickup-pin-btn').addEventListener('click', () => openMiniMap('pickup'));
      document.getElementById('mode-incident-btn').addEventListener('click', () => setMiniMapMode('incident'));
      document.getElementById('mode-pickup-btn').addEventListener('click', () => setMiniMapMode('pickup'));

      // Submit Add Post
      document.getElementById('add-post-form').addEventListener('submit', e => {
        e.preventDefault();
        const type = document.querySelector('input[name="postType"]:checked').value;
        const title = document.getElementById('post-title').value.trim();
        const category = document.getElementById('post-category').value;
        const description = document.getElementById('post-description').value.trim();
        const incidentLabel = document.getElementById('post-incident-loc').value.trim();
        const pickupLabel = document.getElementById('post-pickup-loc').value.trim();

        const newPost = {
          id: 'p_' + Date.now(),
          type,
          title,
          category,
          description,
          image: state.draftLocation.uploadedImage || '',
          authorId: state.currentUser.id,
          createdAt: Date.now(),
          status: 'active',
          incidentLocation: {
            label: incidentLabel,
            lat: state.draftLocation.incidentLat,
            lng: state.draftLocation.incidentLng
          },
          pickupLocation: {
            label: pickupLabel,
            lat: state.draftLocation.pickupLat,
            lng: state.draftLocation.pickupLng
          }
        };

        state.posts.unshift(newPost);
        e.target.reset();
        state.draftLocation.uploadedImage = '';
        document.getElementById('post-photo-preview-wrap').classList.add('hidden');
        document.getElementById('post-photo-name').textContent = 'Optional: upload a photo from your device';
        showToast('Your post is now live on the Home feed and Campus Map!', 'success');
        setView('home');
      });

      // Messages interactions
      document.getElementById('conversation-list').addEventListener('click', e => {
        const btn = e.target.closest('[data-select-chat]');
        if (!btn) return;
        state.activeChatUserId = btn.dataset.selectChat;
        renderMessagesView();
      });

      document.getElementById('chat-form').addEventListener('submit', e => {
        e.preventDefault();
        const input = document.getElementById('chat-input');
        const text = input.value.trim();
        if (!text || !state.activeChatUserId) return;
        state.conversations[state.activeChatUserId].messages.push({
          id: 'm_' + Date.now(),
          senderId: state.currentUser.id,
          text,
          timestamp: Date.now()
        });
        input.value = '';
        renderMessagesView();
      });

      document.getElementById('chat-confirm-return-btn').addEventListener('click', e => {
        const postId = e.currentTarget.dataset.postId;
        if (postId) awardHelpScore(postId);
      });

      // Full Map filters & Satellite toggle
      document.querySelectorAll('.map-filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          state.mapFilter = btn.dataset.mapFilter;
          renderCampusMarkers();
        });
      });

      document.getElementById('map-reset-btn').addEventListener('click', () => {
        if (!campusMap) return;
        campusMap.fitBounds(LPU_MAP_BOUNDS);
      });

      // Profile & Settings
      document.getElementById('open-settings-btn').addEventListener('click', () => {
        document.getElementById('settings-panel').classList.toggle('hidden');
      });
      document.getElementById('close-settings-btn').addEventListener('click', () => {
        document.getElementById('settings-panel').classList.add('hidden');
      });

      document.getElementById('theme-light-btn').addEventListener('click', () => {
        applyTheme('light');
        showToast('Switched to Light theme', 'info');
      });
      document.getElementById('theme-dark-btn').addEventListener('click', () => {
        applyTheme('dark');
        showToast('Switched to Dark theme', 'info');
      });

      document.getElementById('change-username-form').addEventListener('submit', e => {
        e.preventDefault();
        const val = document.getElementById('new-username-input').value.trim().replace(/^@/, '');
        if (!val) return;
        state.currentUser.username = val;
        state.users[state.currentUser.id].username = val;
        document.getElementById('login-hint-user').textContent = `@${val}`;
        renderProfileView();
        showToast(`Username updated to @${val}`, 'success');
      });

      document.getElementById('change-password-form').addEventListener('submit', e => {
        e.preventDefault();
        const curr = document.getElementById('current-password-input').value;
        const next = document.getElementById('new-password-input').value;
        const conf = document.getElementById('confirm-password-input').value;
        if (curr !== state.currentUser.password) {
          showToast('Current password is incorrect.', 'error');
          return;
        }
        if (next.length < 4 || next !== conf) {
          showToast('New passwords must match and be at least 4 characters.', 'error');
          return;
        }
        state.currentUser.password = next;
        e.target.reset();
        showToast('Password updated successfully!', 'success');
      });

      // Logout & Login
      document.getElementById('logout-btn').addEventListener('click', () => {
        state.currentUser.loggedIn = false;
        document.getElementById('login-screen').classList.remove('hidden');
        document.getElementById('login-error').classList.add('hidden');
        document.getElementById('login-username').value = '';
        document.getElementById('login-password').value = '';
        showToast('Logged out of CampusFind', 'info');
      });

      document.getElementById('quick-fill-login').addEventListener('click', () => {
        document.getElementById('login-username').value = state.currentUser.username;
        document.getElementById('login-password').value = state.currentUser.password;
      });

      document.getElementById('login-form').addEventListener('submit', e => {
        e.preventDefault();
        const u = document.getElementById('login-username').value.trim().replace(/^@/, '');
        const p = document.getElementById('login-password').value;
        const err = document.getElementById('login-error');
        if (u === state.currentUser.username && p === state.currentUser.password) {
          state.currentUser.loggedIn = true;
          err.classList.add('hidden');
          document.getElementById('login-screen').classList.add('hidden');
          showToast(`Welcome back, ${state.currentUser.name}!`, 'success');
        } else {
          err.textContent = `Invalid credentials. Use @${state.currentUser.username} and your current password.`;
          err.classList.remove('hidden');
        }
      });
    });
